import csv
with open('inputs/gtfs_extract/stops.txt', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        try:
            lat = float(row['stop_lat'])
            lon = float(row['stop_lon'])
            if lat < -90 or lat > 90 or lon < -180 or lon > 180:
                print(f'INVALID: {row[\"stop_id\"]} lat={lat} lon={lon}')
        except:
            print(f'PARSING ERROR: {row[\"stop_id\"]} lat={row[\"stop_lat\"]} lon={row[\"stop_lon\"]}')
""}

